helpers.layout-entry.ts:
import { flushSync, mount } from "svelte";
import "./app.css";
import JobsDrawer from "./features/jobs/JobsDrawer.svelte";
import { BrowserState } from "./features/browser/browserState.svelte";
import { newFakeApi } from "./features/browser/fakeApi";
import type { JobDTO } from "./lib/api";

const parameters = new URLSearchParams(location.search);
document.documentElement.dataset.theme = parameters.get("theme") ?? "light";
const type = parameters.get("type") ?? "copy";
const long = parameters.get("long") === "true";
const value: JobDTO = {
  id: "layout-job", type, state: "running",
  source: long ? "source/" + "long-scope-".repeat(25) : "src/",
  destination: "dst/", sourceBookmarkId: "a", destBookmarkId: "b",
  createdAt: "2026-09-12T00:00:00Z", startedAt: "2026-09-12T00:00:01Z", finishedAt: "",
  settings: '{"transfers":2,"checkers":4}', engine: "native", error: "", recoveryRecords: 0,
  counters: {
    objectsPlanned: long ? 123456789 : 10, objectsCopied: long ? 12345678 : 3,
    objectsVerified: 0, objectsFailed: long ? 22 : 0, bytesPlanned: 80, bytesCopied: 24,
    overwrites: 0, overwritesRefused: long ? 11 : 0, nativeRouted: 0, objectsDeleted: long ? 7 : 0,
  },
};
const api = newFakeApi();
api.jobs = async () => [structuredClone(value)];
api.job = async () => structuredClone(value);
const browser = new BrowserState(api);
mount(JobsDrawer, { target: document.getElementById("app")!, props: { browser } });
flushSync();
document.querySelector<HTMLButtonElement>(".bar")!.click();
flushSync();
